function reviewProjection(item,rating){
  const stability=Math.max(.5,Number(item.stability||item.intervalDays||1));
  const difficulty=Math.min(10,Math.max(1,Number(item.difficulty||5)));
  if(rating==='again')return {minutes:10,days:0,stability:Math.max(.5,stability*.35),difficulty:Math.min(10,difficulty+.8)};
  if(rating==='hard'){const st=Math.max(1,stability*1.25);return {days:Math.max(1,Math.round(st)),stability:st,difficulty:Math.min(10,difficulty+.25)};}
  if(rating==='good'){const st=Math.max(2,stability*(1.85+(10-difficulty)*.035));return {days:Math.max(2,Math.round(st)),stability:st,difficulty:Math.max(1,difficulty-.12)};}
  const st=Math.max(4,stability*(2.55+(10-difficulty)*.05));return {days:Math.max(4,Math.round(st)),stability:st,difficulty:Math.max(1,difficulty-.3)};
}
function intervalLabel(projection){if(projection.minutes)return `${projection.minutes} min`;const d=projection.days||0;if(d<30)return `${d} j`;if(d<365)return `${Math.round(d/30)} mois`;return `${(d/365).toFixed(1)} an`;}
function rateItem(item,rating){const now=Date.now(),p=reviewProjection(item,rating);const next={...item,stability:p.stability,difficulty:p.difficulty,lastReview:now};if(rating==='again'){next.intervalDays=0;next.successCount=0;next.lapses=(next.lapses||0)+1;next.nextReview=now+p.minutes*60*1000;next.manualFragile=true;}else{next.intervalDays=p.days;next.successCount=(next.successCount||0)+1;next.nextReview=now+p.days*86400000;if(rating==='good'||rating==='easy')delete next.manualFragile;}if(state.words[item.id])state.words[item.id]=next;else state.phrases[item.id]=next;persist();render();}

function lookupWord(surface){const n=wordId(surface);if(glossary[n])return glossary[n];const stem=n.replace(/[.,!?;:]/g,'');if(glossary[stem])return glossary[stem];if(stem.startsWith("d'")){const base=stem.slice(2);if(glossary[base])return {...glossary[base],lemma:glossary[base].lemma||base};const baseAlias=WORD_ALIASES[base];if(baseAlias&&glossary[baseAlias])return {...glossary[baseAlias],lemma:glossary[baseAlias].lemma||baseAlias};}const alias=WORD_ALIASES[stem];if(alias&&glossary[alias])return {...glossary[alias],lemma:glossary[alias].lemma||alias};const cached=cachedDictionaryEntry(stem);return cached||null;}
function tokenHTML(sentence,lesson){
  const keySet=new Set((sentence.keys||[]).map(wordId));
  const parts=sentence.lb.split(/(\p{L}+(?:['’\-]\p{L}+)*)/gu).filter(Boolean);
  return parts.map(p=>{
    if(!/^\p{L}/u.test(p))return esc(p);
    const id=wordId(p),entry=lookupWord(p),lemmaId=entry?.lemma?wordId(entry.lemma):id;
    let priorityKey=keySet.has(lemmaId)?lemmaId:(keySet.has(id)?id:null);
    if(!priorityKey){for(const candidate of keySet){if(id.startsWith(candidate)||candidate.startsWith(id)){priorityKey=candidate;break;}}}
    const saveKey=entry?.lemma?wordId(entry.lemma):(priorityKey||id);
    const saved=state.words[saveKey],seen=state.seen[saveKey]||0;
    let cls='context-word';
    if(priorityKey)cls+=' learnable';
    if(saved?.successCount)cls+=' learned';else if(saved)cls+=' saved';else if(seen>=3)cls+=' familiar';
    if(!entry)cls+=' unknown-word';
    return `<button class="word ${cls}" data-word="${esc(p)}" data-lesson="${lesson.id}">${esc(p)}</button>`;
  }).join('');
}

function estimatedLevel(){const levels=['A1','A2','B1'];const ratios=Object.fromEntries(levels.map(l=>{const all=lessons.filter(x=>x.level===l);const c=all.filter(x=>state.completed.includes(x.id)).length;return [l,all.length?c/all.length:0];})); if(ratios.A2>=.55)return 'B1';if(ratios.A1>=.55)return 'A2';return 'A1';}
