function recommend(){const lvl=estimatedLevel(),order=['A1','A2','B1'],gap=dominantGap();return lessons.map(l=>{let score=0,reason='Pour ton niveau';const diff=order.indexOf(l.level)-order.indexOf(lvl),weak=lessonWeakness(l);if(state.progress[l.id]&&!state.completed.includes(l.id)){score+=120;reason='Continuer';}if(diff===0)score+=40;else if(diff===1){score+=15;reason='Petit défi';}else if(diff===-1){score+=10;reason='Bonne révision';}else score-=25;score+=Math.round(vocabularyFit(l)*28);score+=(l.priority||0)*8;const gapBoost=gapLessonBoost(l,gap?.id);score+=gapBoost;if(gapBoost>=20&&reason!=='Continuer')reason=`Priorité · ${gap.label}`;if((l.priority||0)>=2&&reason==='Pour ton niveau')reason='Utile Sproochentest';if(weak){score+=Math.min(55,weak*10);if(reason!=='Continuer')reason='À consolider';}if(state.completed.includes(l.id))score-=weak?18:55;return {l,score,reason};}).sort((a,b)=>b.score-a.score).slice(0,5);}

