function adaptiveWeeklyTargets(focus){
  const base={reading:3,vocabulary:15,grammar:2,oral:3,listening:2},score=Number(focus?.score||0),boost=score<40?2:score<65?1:0;
  if(focus?.id==='reading')base.reading+=boost;
  if(focus?.id==='vocabulary')base.vocabulary+=boost*5;
  if(focus?.id==='grammar')base.grammar+=boost;
  if(focus?.id==='oral')base.oral+=boost;
  if(focus?.id==='listening')base.listening+=Math.min(1,boost);
  return base;
}
