function saveChallengeAnswer(item,selected){const correct=selected===item.correct,now=Date.now();state.challengeHistory=[...(state.challengeHistory||[]),{question:item.question,kind:item.kind,correct,lessonId:item.lessonId||null,updatedAt:now}].slice(-80);if(item.mistakeId&&state.mistakes?.[item.mistakeId]){const m=state.mistakes[item.mistakeId];if(correct){m.correctStreak=(m.correctStreak||0)+1;m.lastCorrectAt=now;if(m.correctStreak>=2)m.resolved=true;}else{m.wrongCount=(m.wrongCount||0)+1;m.correctStreak=0;m.lastWrongAt=now;}}if(!correct&&item.wordId&&item.lessonId){const l=lessonById(item.lessonId);if(l)ensureWeakWord(l,item.wordId);}persist();return correct;}
