  const frag=fragilitySummary(),primary=frag.top,lesson=lessonById(primary?.lessonId)||recommend()[0]?.l||lessons[0],phrase=frag.phrases.find(x=>lessonById(x.lessonId))||null,topic=oralTopicForLesson(lesson);
