  $('[data-back]').onclick=()=>route('home');$('#open-errors').onclick=()=>route('mistakes');document.querySelectorAll('[data-stats-topic]').forEach(b=>b.onclick=()=>route('sprooch-detail',{sproochTab:'quick',quickLessonId:null,quickTopicId:b.dataset.statsTopic,quickIndex:0,quickRunning:false,quickFinished:false,recordingUrl:null,oralSeconds:30}));bindCommon();
