function strictExamHistory(){return [...(state.examSessions||[])].sort((a,b)=>(b.completedAt||b.updatedAt||0)-(a.completedAt||a.updatedAt||0));}
function strictExamModel(){const id=state.strictExam?.listeningSet;return listeningModels().find(m=>m.id===id)||listeningModels()[0];}
function strictExamPart(){const model=strictExamModel(),i=Math.max(0,Math.min(model.parts.length-1,Number(state.strictExam?.listeningPart)||0));return model.parts[i];}
function strictExamSeconds(startedAt){if(!startedAt)return 300;return Math.max(0,300-Math.floor((Date.now()-Number(startedAt))/1000));}
function strictExamOptions(){const topics=leastPracticedOralTopics(2),photos=leastPracticedPhotoScenes(3),listen=nextMockListeningModel();return {oral:(topics.length>=2?topics:oralTopics.slice(0,2)).map(x=>x.id),photos:(photos.length>=3?photos:photoScenes.slice(0,3)).map(x=>x.id),listeningSet:(listen.m||listeningModels()[0]).id};}
function startStrictExam(){const o=strictExamOptions(),now=Date.now();state.strictExam={id:`strict-${now}`,stage:'oral-choice',startedAt:now,updatedAt:now,oralOptions:o.oral,oralTopic:null,oralStartedAt:null,photoOptions:o.photos,photoScene:null,photoStartedAt:null,listeningSet:o.listeningSet,listeningPart:0,listeningAnswers:{},completedAt:null};setExerciseResume('strictexam',{stage:'oral-choice'});route('strict-exam');}
function setStrictExam(patch={}){if(!state.strictExam)return;state.strictExam={...state.strictExam,...patch,updatedAt:Date.now()};setExerciseResume('strictexam',{stage:state.strictExam.stage});}
function finishStrictTimedStage(kind){stopTimer();endRecording();view.oralRunning=false;view.recordingUrl=null;if(!state.strictExam)return;if(kind==='oral')setStrictExam({stage:'photo-choice',oralEndedAt:Date.now()});else setStrictExam({stage:'listening',photoEndedAt:Date.now(),listeningPart:0});renderStrictExam();}
function startStrictTicker(kind){stopTimer();const key=kind==='oral'?'oralStartedAt':'photoStartedAt';const tick=()=>{const left=strictExamSeconds(state.strictExam?.[key]);const el=$('#strict-timer');if(el)el.textContent=fmt(left);if(left<=0)finishStrictTimedStage(kind);};tick();view.oralTimer=setInterval(tick,1000);}
function strictListeningScore(session=state.strictExam){if(!session)return {got:0,total:0,parts:[]};const model=listeningModels().find(m=>m.id===session.listeningSet)||listeningModels()[0];let got=0,total=0;const parts=model.parts.map(ex=>{const ans=session.listeningAnswers?.[ex.id]||{};let score=0;ex.questions.forEach((q,i)=>{if(Number(ans[i])===q.correct)score++;});got+=score;total+=ex.questions.length;return {id:ex.id,score,total:ex.questions.length,part:ex.part};});return {got,total,parts,pct:total?Math.round(got/total*100):0,model};}
function saveStrictExamResult(){const e=state.strictExam;if(!e)return null;const oralVals=[...document.querySelectorAll('[data-strict-oral]')].map(x=>Number(x.value)),photoVals=[...document.querySelectorAll('[data-strict-photo]')].map(x=>Number(x.value));if(oralVals.length<5||photoVals.length<5)return null;const oralScore=oralVals.reduce((a,b)=>a+b,0)/oralVals.length,photoScore=photoVals.reduce((a,b)=>a+b,0)/photoVals.length,listen=strictListeningScore(e),oralPct=Math.round(oralScore/5*100),photoPct=Math.round(photoScore/5*100),listeningPct=listen.pct,index=Math.round(oralPct*.3+photoPct*.2+listeningPct*.5),now=Date.now();const topic=oralTopics.find(x=>x.id===e.oralTopic),scene=photoScenes.find(x=>x.id===e.photoScene);state.sproochScores.oral=[...(state.sproochScores.oral||[]),{score:oralScore,criteria:oralVals,topic:e.oralTopic,strict:true,updatedAt:now}].slice(-30);state.sproochScores.photo=[...(state.sproochScores.photo||[]),{score:photoScore,criteria:photoVals,scene:e.photoScene,strict:true,updatedAt:now}].slice(-30);for(const p of listen.parts){const ex=listen.model?.parts?.find(x=>x.id===p.id);if(ex)recordListeningResults(ex,listen.model,e.listeningAnswers?.[p.id]||{},{strict:true,now});state.sproochScores.listening[p.id]={score:p.score,total:p.total,updatedAt:now,set:e.listeningSet,part:p.part,strict:true};state.sproochScores.listeningHistory=[...(state.sproochScores.listeningHistory||[]),{partId:p.id,score:p.score,total:p.total,updatedAt:now,set:e.listeningSet,part:p.part,strict:true}].slice(-120);}const summary={id:e.id,startedAt:e.startedAt,completedAt:now,updatedAt:now,oralTopic:e.oralTopic,oralTopicTitle:topic?.title||e.oralTopic,photoScene:e.photoScene,photoSceneTitle:scene?.title||e.photoScene,listeningSet:e.listeningSet,listeningSetTitle:listen.model?.title||e.listeningSet,oralScore,photoScore,oralPct,photoPct,listeningScore:listen.got,listeningTotal:listen.total,listeningPct,index,strict:true};state.examSessions=[...(state.examSessions||[]),summary].slice(-20);state.mockRuns=[...(state.mockRuns||[]),{updatedAt:now,index,oralPct:Math.round((oralPct+photoPct)/2),listeningPct,listeningSet:e.listeningSet,listeningSetTitle:listen.model?.title||e.listeningSet,strict:true}].slice(-30);state.strictExam={...e,stage:'result',completedAt:now,summary};clearExerciseResume('strictexam');persist();return summary;}
function abandonStrictExam(){stopTimer();endRecording();if(!state.strictExam)return route('sprooch');if(confirm('Quitter la simulation ? La session restera enregistrée et pourra être reprise.'))route('sprooch');}
function renderStrictExam(){
  const e=state.strictExam,history=strictExamHistory();
  if(!e){app.innerHTML=`<main class="reader"><header class="reader-top"><button data-back>←</button><div><b>Examen blanc strict</b><small>Simulation séquentielle</small></div></header><section class="tab-pane strict-exam"><div class="strict-intro"><small>MODE STRICT · ENVIRON 45 MIN</small><h1>Une seule progression, sans correction intermédiaire</h1><p>2 choix de thème → 5 min d’entretien → 3 choix de visuel → 5 min de description → 3 parties B1 / 16 questions → bilan final.</p><button class="primary" id="strict-start">Commencer une nouvelle simulation</button></div>${history.length?`<h2>Historique</h2><div class="strict-history">${history.slice(0,5).map(x=>`<article><b>${new Date(x.completedAt).toLocaleDateString('fr-FR')}</b><span>${esc(x.listeningSetTitle||'Modell')}</span><strong>${x.index}%</strong></article>`).join('')}</div>`:''}<p class="settings-note">Simulation interne LëtzLies : ce résultat n’est ni une note INLL ni une prédiction de réussite.</p></section></main>`;$('[data-back]').onclick=()=>route('sprooch');$('#strict-start').onclick=startStrictExam;return;}
  const stages=['oral-choice','oral-ready','oral-run','photo-choice','photo-ready','photo-run','listening','result'],stage=e.stage||'oral-choice',pos=Math.max(0,stages.indexOf(stage)),progress=Math.round(pos/(stages.length-1)*100),model=strictExamModel();
  const header=`<header class="reader-top"><button data-back>←</button><div><b>Examen blanc strict</b><small>${stage==='result'?'Bilan final':`Étape ${Math.min(3,stage.startsWith('oral')?1:stage.startsWith('photo')?2:3)}/3`}</small></div></header>`;
  const meter=`<div class="strict-progress"><i><em style="width:${progress}%"></em></i><span><b class="${stage.startsWith('oral')?'on':''}">1 Oral</b><b class="${stage.startsWith('photo')?'on':''}">2 Visuel</b><b class="${stage==='listening'?'on':''}">3 Écoute</b></span></div>`;
  let body='';
  if(stage==='oral-choice'){const opts=(e.oralOptions||[]).map(id=>oralTopics.find(x=>x.id===id)).filter(Boolean);body=`${meter}<div class="strict-choice"><small>GESPRÉICH A2 · CHOIX DÉFINITIF</small><h1>Choisissez 1 thème sur 2</h1><p>Après validation, il ne sera plus possible de changer de thème pendant cette simulation.</p>${opts.map(t=>`<button data-strict-topic="${t.id}"><b>${esc(t.title)}</b><span>${esc(t.questions[0]||'')}</span></button>`).join('')}</div>`;}
  else if(stage==='oral-ready'){const t=oralTopics.find(x=>x.id===e.oralTopic);body=`${meter}<div class="strict-ready"><small>THÈME VERROUILLÉ</small><h1>${esc(t?.title||'Entretien')}</h1><p>Le chronomètre de 5 minutes démarre au prochain écran. Aucune aide ne sera affichée après le départ.</p><button class="primary" id="strict-oral-start">Lancer les 5 minutes</button></div>`;}
  else if(stage==='oral-run'){const t=oralTopics.find(x=>x.id===e.oralTopic),left=strictExamSeconds(e.oralStartedAt);body=`${meter}<div class="strict-run"><small>GESPRÉICH A2</small><div class="timer" id="strict-timer">${fmt(left)}</div><h1>${esc(t?.title||'Entretien')}</h1><div class="strict-prompts">${(t?.questions||[]).slice(0,5).map((q,i)=>`<article><span>${i+1}</span><p>${esc(q)}</p></article>`).join('')}</div><p class="strict-no-score">Pas de correction ni d’aide pendant la simulation.</p></div>`;}
  else if(stage==='photo-choice'){const opts=(e.photoOptions||[]).map(id=>photoScenes.find(x=>x.id===id)).filter(Boolean);body=`${meter}<div class="strict-choice"><small>BILDBESCHREIWUNG A2 · CHOIX DÉFINITIF</small><h1>Choisissez 1 visuel sur 3</h1><div class="strict-photo-grid">${opts.map(p=>`<button data-strict-photo="${p.id}"><img src="${esc(p.image)}" alt=""><b>${esc(p.title)}</b></button>`).join('')}</div></div>`;}
  else if(stage==='photo-ready'){const p=photoScenes.find(x=>x.id===e.photoScene);body=`${meter}<div class="strict-ready"><small>VISUEL VERROUILLÉ</small><img class="strict-selected-photo" src="${esc(p?.image||'')}" alt=""><h1>${esc(p?.title||'Description')}</h1><p>Au prochain écran, vous aurez 5 minutes. Les aides de description ne seront pas affichées.</p><button class="primary" id="strict-photo-start">Lancer les 5 minutes</button></div>`;}
  else if(stage==='photo-run'){const p=photoScenes.find(x=>x.id===e.photoScene),left=strictExamSeconds(e.photoStartedAt);body=`${meter}<div class="strict-run"><small>BILDBESCHREIWUNG A2</small><div class="timer" id="strict-timer">${fmt(left)}</div><img class="strict-selected-photo" src="${esc(p?.image||'')}" alt="${esc(p?.title||'')}"><p class="strict-no-score">Décrivez uniquement ce que vous pouvez formuler spontanément.</p></div>`;}
  else if(stage==='listening'){const ex=strictExamPart(),partIndex=Number(e.listeningPart)||0,ans=e.listeningAnswers?.[ex.id]||{},answered=Object.keys(ans).length;body=`${meter}<div class="strict-listening"><small>HÉIERVERSTOEN B1 · ${esc(model.title)} · PARTIE ${partIndex+1}/3</small><h1>${esc(ex.title)}</h1><div class="listen-kind">${esc(listeningKindLabel(ex.kind))}</div><button class="audio-big" data-speak="${esc(ex.text)}">▶ Écouter</button><div class="listen-qs">${ex.questions.map((q,qi)=>`<article><b>${qi+1}. ${esc(q.question)}</b>${q.answers.map((a,i)=>`<label><input type="radio" name="strictq${qi}" value="${i}" ${Number(ans[qi])===i?'checked':''}> ${esc(a)}</label>`).join('')}</article>`).join('')}</div><button class="primary" id="strict-listen-next" ${answered<ex.questions.length?'disabled':''}>${partIndex<2?'Valider et passer à la partie suivante':'Valider et terminer le test'}</button><p class="strict-no-score">${answered}/${ex.questions.length} réponses enregistrées. Aucun corrigé avant le bilan final.</p></div>`;}
  else {const sum=e.summary||strictListeningScore(e);body=`${meter}<div class="strict-result"><small>BILAN FINAL</small><h1>${e.summary?`${e.summary.index}%`:'Auto-évaluez les deux parties orales'}</h1>${e.summary?`<div class="strict-result-grid"><article><b>${e.summary.oralPct}%</b><span>entretien</span></article><article><b>${e.summary.photoPct}%</b><span>description</span></article><article><b>${e.summary.listeningPct}%</b><span>écoute B1 · ${e.summary.listeningScore}/${e.summary.listeningTotal}</span></article></div><p>Indice interne d’entraînement. Il ne correspond pas à une note officielle.</p><button class="primary" id="strict-finish">Terminer la simulation</button>`:`<p>L’écoute est corrigée maintenant. Pour les deux parties orales, notez votre prestation après coup, sans modifier ce que vous avez fait.</p><div class="strict-assess"><h2>Entretien A2</h2>${['Vocabulaire','Fluidité','Clarté','Grammaire','Cohérence'].map((x,i)=>`<label><span>${x}</span><input type="range" min="1" max="5" value="3" data-strict-oral="${i}"><output>3</output></label>`).join('')}<h2>Description A2</h2>${['Détails','Cohérence','Vocabulaire','Fluidité','Clarté'].map((x,i)=>`<label><span>${x}</span><input type="range" min="1" max="5" value="3" data-strict-photo="${i}"><output>3</output></label>`).join('')}<button class="primary" id="strict-save-result">Calculer le bilan final</button></div>`}</div>`;}
  app.innerHTML=`<main class="reader">${header}<section class="tab-pane strict-exam">${body}</section></main>`;bindCommon();$('[data-back]').onclick=abandonStrictExam;
  document.querySelectorAll('[data-strict-topic]').forEach(b=>b.onclick=()=>{const t=oralTopics.find(x=>x.id===b.dataset.strictTopic);if(confirm(`Verrouiller le thème « ${t?.title||''} » ?`)){setStrictExam({oralTopic:b.dataset.strictTopic,stage:'oral-ready'});renderStrictExam();}});
  $('#strict-oral-start')?.addEventListener('click',async()=>{view.recordingUrl=null;view.oralRunning=true;const ok=await beginRecording();setStrictExam({stage:'oral-run',oralStartedAt:Date.now(),oralRecorded:ok});renderStrictExam();});
  document.querySelectorAll('[data-strict-photo]').forEach(b=>b.onclick=()=>{const p=photoScenes.find(x=>x.id===b.dataset.strictPhoto);if(confirm(`Verrouiller le visuel « ${p?.title||''} » ?`)){setStrictExam({photoScene:b.dataset.strictPhoto,stage:'photo-ready'});renderStrictExam();}});
  $('#strict-photo-start')?.addEventListener('click',async()=>{view.recordingUrl=null;view.oralRunning=true;const ok=await beginRecording();setStrictExam({stage:'photo-run',photoStartedAt:Date.now(),photoRecorded:ok});renderStrictExam();});
  document.querySelectorAll('.strict-listening input[type=radio]').forEach(r=>r.onchange=()=>{const ex=strictExamPart(),qi=Number(r.name.replace('strictq','')),answers={...(state.strictExam.listeningAnswers||{})};answers[ex.id]={...(answers[ex.id]||{}),[qi]:Number(r.value)};setStrictExam({listeningAnswers:answers});const n=Object.keys(answers[ex.id]).length;if(n>=ex.questions.length)$('#strict-listen-next')?.removeAttribute('disabled');});
  $('#strict-listen-next')?.addEventListener('click',()=>{const i=Number(state.strictExam.listeningPart)||0;if(i<2)setStrictExam({listeningPart:i+1});else setStrictExam({stage:'result'});renderStrictExam();});
  document.querySelectorAll('[data-strict-oral],[data-strict-photo]').forEach(r=>r.oninput=()=>r.nextElementSibling.textContent=r.value);
  $('#strict-save-result')?.addEventListener('click',()=>{saveStrictExamResult();renderStrictExam();});
  $('#strict-finish')?.addEventListener('click',()=>{state.strictExam=null;persist();route('sprooch');});
  if(stage==='oral-run')startStrictTicker('oral');if(stage==='photo-run')startStrictTicker('photo');
}

function renderSprooch(){
  const bank=listeningBankStats(),ref=listeningReferenceSnapshot(),ready=sproochReadiness(),diag=examDiagnostic(),oralAvg=averagePractice('oral'),photoAvg=averagePractice('photo'),quick=quickOralStats();
  const topicStats=oralTopicProgress(),weak=weakestOralTopic();
  shell(`<section class="screen"><header class="page-head"><span>Objectif examen</span><h1>Sproochentest</h1><p>Readle pour apprendre, entraînement ciblé pour réussir.</p></header><div class="readiness-card"><div><small>INDICE D’ENTRAÎNEMENT</small><b>${ready.score}%</b><span>Ce n’est pas une prédiction de réussite : il mesure seulement votre entraînement dans l’app.</span></div><i><em style="width:${ready.score}%"></em></i></div><button class="exam-path-card" data-nav="readiness"><small>PARCOURS EXAMEN</small><b>${diag.overall}% · ${esc(diag.stage)}</b><span>${diag.done}/${diag.total} jalons atteints · priorité : ${esc(diag.next.label)}</span><em>Voir le diagnostic →</em></button><button class="exam-prep-mini" data-nav="exam-prep"><b>Révision express avant examen</b><span>~20 min ciblées selon les faiblesses du moment</span><em>→</em></button><button class="strict-exam-entry" data-nav="strict-exam"><small>SIMULATION STRICTE</small><b>${state.strictExam?'Reprendre l’examen blanc strict':'Examen blanc strict'}</b><span>${state.strictExam?'Session en cours · reprise au bon stade':'Choix verrouillés · 5 min + 5 min · 16 questions B1 · bilan seulement à la fin'}</span><em>→</em></button><div class="exam-summary"><div><b>${oralAvg?oralAvg.toFixed(1)+'/5':oralTopics.length}</b><span>${oralAvg?'oral auto-évalué':'thèmes A2'}</span></div><div><b>${photoAvg?photoAvg.toFixed(1)+'/5':photoScenes.length}</b><span>${photoAvg?'visuels auto-évalués':'visuels A2'}</span></div><div><b>${bank.complete}/${bank.total}</b><span>modèles B1 terminés</span></div></div><button class="quick-oral-entry" data-sprooch="quick"><small>RÉPONSE FLASH · 30 S</small><b>${quick.attempts?`Moyenne ${quick.avg.toFixed(1)}/5`:'Commencer par une question courte'}</b><span>Thème prioritaire : ${esc(weak.title)}. Une réponse, une réécoute, puis consolidation automatique si nécessaire.</span><em>Répondre →</em></button><div class="sprooch-grid"><button data-sprooch="oral"><b>🎤 Gespréich A2</b><span>10 thèmes · rotation des sujets</span></button><button data-sprooch="photo"><b>▧ Bildbeschreiwung A2</b><span>${photoScenes.length} visuels · chrono 5 min</span></button><button data-sprooch="listening"><b>🎧 Héierverstoen B1</b><span>${bank.total} modèles · ${bank.questions} questions · référence ${ref.pct||0}%</span></button><button data-sprooch="mock"><b>◎ Test blanc</b><span>Rotation anti-répétition + historique</span></button></div><h2 class="sprooch-subtitle">Thèmes oraux</h2><div class="oral-topic-grid">${topicStats.map(x=>`<button data-quick-topic="${x.topic.id}" class="${x.topic.id===weak.id?'weak':''}"><span>${esc(x.topic.title)}</span><b>${x.attempts?x.avg.toFixed(1)+'/5':'—'}</b><small>${x.attempts?`${x.attempts} essai${x.attempts>1?'s':''}`:'À essayer'}${x.topic.id===weak.id?' · priorité':''}</small></button>`).join('')}</div></section>`,'sprooch');
  document.querySelectorAll('[data-sprooch]').forEach(b=>b.onclick=()=>route('sprooch-detail',{sproochTab:b.dataset.sprooch,quickLessonId:null,quickTopicId:b.dataset.sprooch==='quick'?weak.id:null,quickIndex:0,quickRunning:false,quickFinished:false,recordingUrl:null,oralSeconds:b.dataset.sprooch==='quick'?30:300,listeningSet:b.dataset.sprooch==='listening'?ref.index:0,listeningPart:0,mockListeningSet:null}));
  document.querySelectorAll('[data-quick-topic]').forEach(b=>b.onclick=()=>route('sprooch-detail',{sproochTab:'quick',quickLessonId:null,quickTopicId:b.dataset.quickTopic,quickIndex:0,quickRunning:false,quickFinished:false,recordingUrl:null,oralSeconds:30}));
}
function renderSproochDetail(){if(view.sproochTab==='quick')return renderQuickOral();if(view.sproochTab==='oral')return renderOral();if(view.sproochTab==='listening')return renderListening();if(view.sproochTab==='photo')return renderPhoto();return renderMockTest();}
let mediaRecorder=null,recordChunks=[];
async function beginRecording(){try{if(!navigator.mediaDevices?.getUserMedia)return false;const stream=await navigator.mediaDevices.getUserMedia({audio:true});recordChunks=[];const recorder=new MediaRecorder(stream);mediaRecorder=recorder;recorder.ondataavailable=e=>{if(e.data.size)recordChunks.push(e.data);};recorder.onstop=()=>{const blob=new Blob(recordChunks,{type:recorder.mimeType||'audio/webm'});if(view.recordingUrl)URL.revokeObjectURL(view.recordingUrl);view.recordingUrl=URL.createObjectURL(blob);stream.getTracks().forEach(t=>t.stop());};recorder.start();return true;}catch{return false;}}
function endRecording(){try{if(mediaRecorder?.state==='recording')mediaRecorder.stop();}catch{}mediaRecorder=null;}
function renderQuickOral(){
  const prompt=quickPromptFor(view.quickLessonId,view.quickIndex,view.quickTopicId),l=prompt.lesson,topic=prompt.topic||oralTopics[0],finished=view.quickFinished&&!view.quickRunning;
  const latest=[...(state.sproochScores?.quick||[])].filter(x=>x.topic===topic.id&&(!l||x.lessonId===l.id)).sort((a,b)=>(b.updatedAt||0)-(a.updatedAt||0))[0];
  app.innerHTML=`<main class="reader"><header class="reader-top"><button data-back>←</button><div><b>Répondre en 30 s</b><small>${esc(topic.title)}${l?` · ${esc(l.title)}`:''}</small></div></header><section class="tab-pane quick-oral-pane">${l?`<button class="quick-story-source" data-open-lesson="${l.id}" ${view.quickRunning?'disabled':''}><small>À PARTIR DE L’HISTOIRE</small><b>${esc(l.title)}</b><span>${esc(l.description)}</span></button>`:''}<div class="quick-prompt"><small>QUESTION A2 · 30 SECONDES</small><h1>${esc(prompt.question)}</h1><div class="timer" id="timer">${fmt(view.oralSeconds||30)}</div></div><button class="primary" id="quick-start">${view.quickRunning?'■ Terminer':'● '+(finished?'Refaire 30 secondes':'Commencer 30 secondes')}</button>${finished?`<div class="quick-after">${view.recordingUrl?`<div class="recording-box"><b>Votre réponse</b><audio controls src="${esc(view.recordingUrl)}"></audio></div>`:'<p class="quick-no-record">Micro non disponible : vous pouvez tout de même vous auto-évaluer.</p>'}<div class="self-assess quick-assess"><b>Auto-évaluation</b><p>Après réécoute, notez uniquement ce que vous avez réellement réussi.</p>${['Vocabulaire','Fluidité','Grammaire'].map((x,i)=>`<label><span>${x}</span><input type="range" min="1" max="5" value="3" data-assess-quick="${i}"><output>3</output></label>`).join('')}<button class="secondary" id="save-quick-assess">Enregistrer et consolider</button><p id="quick-feedback" class="quick-feedback"></p></div><details class="quick-help" open><summary>Aides pour refaire la réponse</summary>${prompt.followups.map(x=>`<span>${esc(x)}</span>`).join('')}${prompt.words.length?`<div class="quick-words"><small>MOTS DE L’HISTOIRE</small>${prompt.words.map(x=>`<em>${esc(x)}</em>`).join('')}</div>`:''}${topic.starters?.length?`<div class="quick-starters"><small>DÉBUTS DE PHRASES</small>${topic.starters.slice(0,4).map(x=>`<em>${esc(x)}</em>`).join('')}</div>`:''}</details><button class="text-button" id="quick-next">Question suivante →</button></div>`:`<details class="quick-help"><summary>Voir les aides seulement après un premier essai</summary><p>Répondez d’abord sans lire d’aide. L’objectif est de retrouver activement le vocabulaire.</p></details>`}${latest&&!finished?`<p class="quick-last">Dernier score sur ce thème : <b>${Number(latest.score).toFixed(1)}/5</b></p>`:''}</section></main>`;
  bindCommon();
  $('[data-back]').onclick=()=>{stopTimer();endRecording();if(l)route('lesson',{lessonId:l.id,tab:'story'});else route('sprooch');};
  $('#quick-start').onclick=async()=>{if(view.quickRunning){stopTimer();endRecording();view.quickRunning=false;view.quickFinished=true;setTimeout(renderQuickOral,160);return;}if(view.recordingUrl){try{URL.revokeObjectURL(view.recordingUrl);}catch{}view.recordingUrl=null;}view.quickRunning=true;view.quickFinished=false;view.oralSeconds=30;setExerciseResume('oralquick',{lessonId:l?.id||null,topicId:topic.id,index:view.quickIndex});await beginRecording();renderQuickOral();startCountdown(()=>{endRecording();view.quickRunning=false;view.quickFinished=true;setTimeout(renderQuickOral,160);});};
  document.querySelectorAll('[data-assess-quick]').forEach(r=>r.oninput=()=>r.nextElementSibling.textContent=r.value);
  $('#save-quick-assess')?.addEventListener('click',()=>{const vals=[...document.querySelectorAll('[data-assess-quick]')].map(x=>Number(x.value));if(!vals.length)return;const score=vals.reduce((a,b)=>a+b,0)/vals.length,cons=saveQuickOral(prompt,score,{criteria:vals});clearExerciseResume('oralquick');$('#save-quick-assess').disabled=true;$('#save-quick-assess').textContent=`✓ Enregistré · ${score.toFixed(1)}/5`;const parts=[];if(cons.words)parts.push(`${cons.words} mot${cons.words>1?'s':''} remis en révision`);if(cons.grammar)parts.push('1 règle ajoutée au carnet');$('#quick-feedback').textContent=parts.length?`Consolidation : ${parts.join(' · ')}.`:'Aucune consolidation supplémentaire nécessaire.';});
  $('#quick-next')?.addEventListener('click',()=>{if(view.recordingUrl){try{URL.revokeObjectURL(view.recordingUrl);}catch{}view.recordingUrl=null;}view.quickIndex++;view.quickFinished=false;view.quickRunning=false;view.oralSeconds=30;renderQuickOral();});
}
function renderOral(){const t=oralTopics[view.oralTopic];app.innerHTML=`<main class="reader"><header class="reader-top"><button data-back>←</button><div><b>Gespréich A2</b><small>5 Minuten</small></div></header><section class="tab-pane oral"><select id="oral-topic" ${view.oralRunning?'disabled':''}>${oralTopics.map((x,i)=>`<option value="${i}" ${i===view.oralTopic?'selected':''}>${x.title}</option>`).join('')}</select><div class="timer" id="timer">${fmt(view.oralSeconds)}</div><div class="oral-qs">${t.questions.map((q,i)=>`<div><span>${i+1}</span><p>${esc(q)}</p></div>`).join('')}</div><button class="primary" id="oral-start">${view.oralRunning?'■ Terminer':'● Commencer 5 minutes'}</button>${view.recordingUrl&&!view.oralRunning?`<div class="recording-box"><b>Votre entraînement</b><audio controls src="${esc(view.recordingUrl)}"></audio></div><div class="self-assess"><b>Auto-évaluation</b><p>Notez votre prestation après réécoute.</p>${['Vocabulaire','Fluidité','Clarté','Grammaire','Cohérence'].map((x,i)=>`<label><span>${x}</span><input type="range" min="1" max="5" value="3" data-assess-oral="${i}"><output>3</output></label>`).join('')}<button class="secondary" id="save-oral-assess">Enregistrer l’auto-évaluation</button></div>`:''}${!view.oralRunning?`<details><summary>Aides après entraînement</summary>${t.starters.map(x=>`<span class="help-phrase">${esc(x)}</span>`).join('')}</details>`:''}</section></main>`;$('[data-back]').onclick=()=>{stopTimer();endRecording();route('sprooch');};$('#oral-topic').onchange=e=>{view.oralTopic=Number(e.target.value);view.oralSeconds=300;renderOral();};$('#oral-start').onclick=async()=>{if(view.oralRunning){stopTimer();endRecording();view.oralRunning=false;setTimeout(renderOral,120);}else{view.recordingUrl=null;view.oralRunning=true;view.oralSeconds=300;await beginRecording();renderOral();startCountdown(()=>{endRecording();view.oralRunning=false;setTimeout(renderOral,120);});}};document.querySelectorAll('[data-assess-oral]').forEach(r=>r.oninput=()=>r.nextElementSibling.textContent=r.value);$('#save-oral-assess')?.addEventListener('click',()=>{const vals=[...document.querySelectorAll('[data-assess-oral]')].map(x=>Number(x.value));if(!vals.length)return;const score=vals.reduce((a,b)=>a+b,0)/vals.length;state.sproochScores.oral=[...(state.sproochScores.oral||[]),{score,topic:t.id,updatedAt:Date.now()}].slice(-30);persist();$('#save-oral-assess').textContent=`✓ Enregistré · ${score.toFixed(1)}/5`;});}
function startCountdown(onEnd){stopTimer();view.oralTimer=setInterval(()=>{view.oralSeconds--;const el=$('#timer');if(el)el.textContent=fmt(view.oralSeconds);if(view.oralSeconds<=0){stopTimer();onEnd?.();}},1000);}
function stopTimer(){if(view.oralTimer){clearInterval(view.oralTimer);view.oralTimer=null;}}
function fmt(s){return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`;}
function renderPhoto(){const scene=photoScenes[view.photoIndex%photoScenes.length],criteria=['Détails','Cohérence','Vocabulaire','Fluidité','Clarté'],latest=[...(state.sproochScores?.photo||[])].filter(x=>x.scene===scene.id).sort((a,b)=>(b.updatedAt||0)-(a.updatedAt||0))[0];app.innerHTML=`<main class="reader"><header class="reader-top"><button data-back>←</button><div><b>Bildbeschreiwung A2</b><small>5 Minuten</small></div></header><section class="tab-pane oral"><select id="photo-scene" ${view.oralRunning?'disabled':''}>${photoScenes.map((x,i)=>`<option value="${i}" ${i===view.photoIndex?'selected':''}>${x.title}</option>`).join('')}</select><img class="photo-scene" src="${esc(scene.image)}" alt="${esc(scene.title)}"><div class="timer" id="timer">${fmt(view.oralSeconds)}</div>${!view.oralRunning?`<div class="photo-help"><b>Après l’essai, vérifiez si vous avez parlé de :</b>${scene.prompts.map(x=>`<span>${esc(x)}</span>`).join('')}</div>`:''}<button class="primary" id="photo-start">${view.oralRunning?'■ Terminer':'● Commencer 5 minutes'}</button>${view.recordingUrl&&!view.oralRunning?`<div class="recording-box"><b>Votre description</b><audio controls src="${esc(view.recordingUrl)}"></audio></div><div class="self-assess"><b>Auto-évaluation · 5 critères</b><p>Notez la prestation après l’essai, comme dans le bilan du test strict.</p>${criteria.map((x,i)=>`<label><span>${x}</span><input type="range" min="1" max="5" value="${latest?.criteria?.[i]||3}" data-assess-photo="${i}"><output>${latest?.criteria?.[i]||3}</output></label>`).join('')}<button class="secondary" id="save-photo-assess">Enregistrer</button></div>`:''}</section></main>`;$('[data-back]').onclick=()=>{stopTimer();endRecording();route('sprooch');};$('#photo-scene').onchange=e=>{view.photoIndex=Number(e.target.value);view.oralSeconds=300;renderPhoto();};$('#photo-start').onclick=async()=>{if(view.oralRunning){stopTimer();endRecording();view.oralRunning=false;setTimeout(renderPhoto,120);}else{view.recordingUrl=null;view.oralRunning=true;view.oralSeconds=300;await beginRecording();renderPhoto();startCountdown(()=>{endRecording();view.oralRunning=false;setTimeout(renderPhoto,120);});}};document.querySelectorAll('[data-assess-photo]').forEach(r=>r.oninput=()=>r.nextElementSibling.textContent=r.value);$('#save-photo-assess')?.addEventListener('click',()=>{const vals=[...document.querySelectorAll('[data-assess-photo]')].map(r=>Number(r.value));if(vals.length!==5)return;const score=vals.reduce((a,b)=>a+b,0)/vals.length;state.sproochScores.photo=[...(state.sproochScores.photo||[]),{score,criteria:vals,scene:scene.id,updatedAt:Date.now()}].slice(-30);persist();$('#save-photo-assess').textContent=`✓ Enregistré · ${score.toFixed(1)}/5`;});}
function renderListening(){const models=listeningModels(),model=models[view.listeningSet%models.length]||models[0],parts=model.parts,ex=parts[view.listeningPart%parts.length];state.exerciseProgress=state.exerciseProgress||{quiz:{},listening:{},last:null};state.exerciseProgress.listening=state.exerciseProgress.listening||{};const savedAnswers=state.exerciseProgress.listening[ex.id]||{};setExerciseResume('listening',{set:view.listeningSet,part:view.listeningPart});const stored=state.sproochScores?.listening?.[ex.id],snap=listeningModelSnapshot(view.listeningSet),history=listeningAttempts(ex.id).slice(0,5),recent=listeningRecentStats();app.innerHTML=`<main class="reader"><header class="reader-top"><button data-back>←</button><div><b>Héierverstoen B1</b><small>${esc(model.title)} · 5 + 4 + 7</small></div></header><section class="tab-pane"><div class="listen-models">${models.map((m,i)=>{const x=listeningModelSnapshot(i);return `<button data-listen-set="${i}" class="${i===view.listeningSet?'on':''}"><b>${esc(m.title)}</b><small>${x.done}/3 · ${x.total?x.pct+'%':'nouveau'}</small></button>`;}).join('')}</div><div class="listen-parts">${parts.map((x,i)=>`<button data-listen-part="${i}" class="${i===view.listeningPart?'on':''}">Partie ${i+1}<small>${esc(listeningKindLabel(x.kind))} · ${x.questions.length} questions</small></button>`).join('')}</div><div class="listen-model-progress"><span>${snap.done}/3 parties corrigées</span><b>${snap.total?`${snap.got}/${snap.total} · ${snap.pct}%`:'16 questions à faire'}</b></div>${recent.rows.length>=3?`<div class="listen-trend"><small>9 DERNIÈRES TENTATIVES</small><b>${recent.pct}%</b><span>${esc(recent.label)}</span></div>`:''}<div class="listen-kind">${esc(listeningKindLabel(ex.kind))}</div><h2>${esc(ex.title)}</h2><button class="audio-big" data-speak="${esc(ex.text)}">▶ Écouter</button><div class="listen-qs">${ex.questions.map((q,qi)=>`<article><b>${qi+1}. ${esc(q.question)}</b>${q.answers.map((a,i)=>`<label><input type="radio" name="q${qi}" value="${i}" ${Number(savedAnswers[qi])===i?'checked':''}> ${esc(a)}</label>`).join('')}</article>`).join('')}</div><button class="primary" id="check-listen">Corriger cette partie</button><p id="listen-score" class="listen-score">${stored?`Dernier score : ${stored.score}/${stored.total}`:''}</p>${history.length?`<div class="listen-history"><small>HISTORIQUE DE CETTE PARTIE</small>${history.map(x=>`<div><span>${new Date(x.updatedAt).toLocaleDateString('fr-FR')}</span><b>${x.score}/${x.total}</b><em>${Math.round(x.score/x.total*100)}%${x.strict?' · strict':''}</em></div>`).join('')}</div>`:''}</section></main>`;bindCommon();$('[data-back]').onclick=()=>{if(view.mockListeningSet!==null&&view.mockListeningSet!==undefined){view.sproochTab='mock';renderMockTest();}else route('sprooch');};document.querySelectorAll('[data-listen-set]').forEach(b=>b.onclick=()=>{view.listeningSet=Number(b.dataset.listenSet);view.listeningPart=0;renderListening();});document.querySelectorAll('[data-listen-part]').forEach(b=>b.onclick=()=>{view.listeningPart=Number(b.dataset.listenPart);renderListening();});document.querySelectorAll('.listen-qs input[type=radio]').forEach(r=>r.onchange=()=>{const qi=Number(r.name.slice(1));state.exerciseProgress.listening[ex.id]={...(state.exerciseProgress.listening[ex.id]||{}),[qi]:Number(r.value)};persist();});$('#check-listen').onclick=()=>{let score=0;const answers={};ex.questions.forEach((q,i)=>{const v=document.querySelector(`input[name=q${i}]:checked`);if(v)answers[i]=Number(v.value);if(v&&Number(v.value)===q.correct)score++;});const now=Date.now();const wrongCount=recordListeningResults(ex,model,answers,{strict:false,now});state.sproochScores=state.sproochScores||{listening:{},listeningHistory:[]};state.sproochScores.listening=state.sproochScores.listening||{};state.sproochScores.listening[ex.id]={score,total:ex.questions.length,updatedAt:now,set:model.id,part:ex.part};state.sproochScores.listeningHistory=[...(state.sproochScores.listeningHistory||[]),{partId:ex.id,score,total:ex.questions.length,updatedAt:now,set:model.id,part:ex.part,strict:false}].slice(-120);persist();clearExerciseResume('listening');const after=listeningModelSnapshot(view.listeningSet),trend=listeningRecentStats();$('#listen-score').innerHTML=`Score : <b>${score}/${ex.questions.length}</b>. ${after.complete?`Modèle terminé : ${after.got}/${after.total} (${after.pct} %).`:score>=Math.ceil(ex.questions.length*.65)?'Bon niveau sur cette partie.':'Réécoutez en cherchant les informations clés.'}${trend.rows.length>=3?` Tendance récente : ${trend.pct} %.`:''}${wrongCount?` <button class="listen-remediation-link" data-nav="mistakes">${wrongCount} erreur${wrongCount>1?'s':''} à comprendre →</button>`:''}`;bindCommon();};}
function renderMockTest(){if(view.mockListeningSet===null||view.mockListeningSet===undefined)view.mockListeningSet=nextMockListeningModel().i;const topics=leastPracticedOralTopics(2),t1=topics[0]||oralTopics[0],t2=topics[1]||oralTopics[1],pics=leastPracticedPhotoScenes(3),model=listeningModels()[view.mockListeningSet]||listeningModels()[0],snap=mockTrainingSnapshot(view.mockListeningSet),history=[...(state.mockRuns||[])].sort((a,b)=>(b.updatedAt||0)-(a.updatedAt||0));app.innerHTML=`<main class="reader"><header class="reader-top"><button data-back>←</button><div><b>Test blanc</b><small>Simulation guidée · rotation anti-répétition</small></div></header><section class="tab-pane mock-test"><h1>Sproochentest blanc</h1><article><small>1 · GESPRÉICH · 5 MIN</small><h2>Choisissez un thème</h2><div class="mock-choice"><button data-mock-oral="${oralTopics.indexOf(t1)}">${esc(t1.title)}</button><button data-mock-oral="${oralTopics.indexOf(t2)}">${esc(t2.title)}</button></div><p class="mock-rotation-note">Les thèmes les moins travaillés sont proposés en priorité.</p></article><article><small>2 · BILDBESCHREIWUNG · 5 MIN</small><h2>Choisissez un visuel</h2><div class="mock-photos">${pics.map(p=>`<button data-mock-photo="${photoScenes.indexOf(p)}"><img src="${esc(p.image)}" alt=""><span>${esc(p.title)}</span></button>`).join('')}</div></article><article><small>3 · HÉIERVERSTOEN B1</small><h2>${esc(model.title)} · 16 questions</h2><p>${snap.lTotal?`Résultat de ce modèle : ${snap.lScore}/${snap.lTotal}`:'Ce modèle n’a pas encore été complété.'}</p><div class="mock-listen-models">${listeningModels().map((m,i)=>`<button data-mock-set="${i}" class="${i===view.mockListeningSet?'on':''}">${esc(m.title)}</button>`).join('')}</div><button class="primary" id="mock-listening">Commencer les 3 parties</button></article><article class="mock-summary"><small>BILAN D’ENTRAÎNEMENT</small><h2>${snap.index}%</h2><div><span>Oral / visuel <b>${snap.oralPct}%</b></span><span>Écoute B1 <b>${snap.listeningPct}%</b></span></div><p>Indice interne d’entraînement, pas un résultat officiel ni une prédiction de réussite.</p><button class="secondary" id="save-mock" ${!snap.complete?'disabled':''}>${snap.complete?'Enregistrer ce bilan':'Faites oral, visuel et les 3 parties du modèle'}</button></article>${history.length?`<article class="mock-run-history"><small>HISTORIQUE · 5 DERNIERS</small>${history.slice(0,5).map(x=>`<div><b>${new Date(x.updatedAt).toLocaleDateString('fr-FR')}</b><span>${esc(x.listeningSetTitle||x.listeningSet||'Modell 1')}</span><strong>${x.index}%</strong></div>`).join('')}</article>`:''}</section></main>`;$('[data-back]').onclick=()=>{view.mockListeningSet=null;route('sprooch');};document.querySelectorAll('[data-mock-oral]').forEach(b=>b.onclick=()=>{view.oralTopic=Number(b.dataset.mockOral);view.oralSeconds=300;view.sproochTab='oral';renderOral();});document.querySelectorAll('[data-mock-photo]').forEach(b=>b.onclick=()=>{view.photoIndex=Number(b.dataset.mockPhoto);view.oralSeconds=300;view.sproochTab='photo';renderPhoto();});document.querySelectorAll('[data-mock-set]').forEach(b=>b.onclick=()=>{view.mockListeningSet=Number(b.dataset.mockSet);renderMockTest();});$('#mock-listening').onclick=()=>{view.listeningSet=view.mockListeningSet;view.listeningPart=0;view.sproochTab='listening';renderListening();};$('#save-mock')?.addEventListener('click',()=>{const saved=saveMockRun();$('#save-mock').textContent=`✓ Bilan enregistré · ${saved.index}%`;});}

async function speak(text){unlockAudioGesture();try{await speakLuxembourgish(text,{voice:state.audio.voice,rate:state.audio.rate});}catch{alert('Audio luxembourgeois indisponible pour le moment. Vérifie la connexion au premier chargement de Mia/Mil.');}}

function bindCommon(){document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>route(b.dataset.nav));document.querySelectorAll('[data-open-lesson]').forEach(b=>b.onclick=()=>route('lesson',{lessonId:b.dataset.openLesson,tab:'story',focusSentence:null,quizIndex:0,quizScore:0,quizAnswered:null}));document.querySelectorAll('[data-fav]').forEach(b=>b.onclick=e=>{e.stopPropagation();toggleFavorite(b.dataset.fav);});document.querySelectorAll('[data-word]').forEach(b=>b.onclick=e=>{e.stopPropagation();renderWordSheet(b.dataset.word,b.dataset.lesson);});document.querySelectorAll('[data-speak]').forEach(b=>b.onclick=e=>{e.stopPropagation();speak(b.dataset.speak);});}

function render(){applyReaderScale();if(view.screen==='home')return renderHome();if(view.screen==='today')return renderToday();if(view.screen==='consolidation')return renderConsolidation();if(view.screen==='weekly')return renderWeekly();if(view.screen==='challenge')return renderChallenge();if(view.screen==='library')return renderLibrary();if(view.screen==='lesson')return renderLesson();if(view.screen==='lesson-complete')return renderLessonComplete();if(view.screen==='shadow')return renderShadowing();if(view.screen==='dictation')return renderDictation();if(view.screen==='review')return renderReview();if(view.screen==='grammar-book')return renderGrammarBook();if(view.screen==='mistakes')return renderMistakes();if(view.screen==='remediation')return renderRemediation();if(view.screen==='search')return renderSearch();if(view.screen==='books')return renderBooks();if(view.screen==='book')return renderBook();if(view.screen==='settings')return renderSettings();if(view.screen==='stats')return renderStats();if(view.screen==='readiness')return renderReadiness();if(view.screen==='exam-prep')return renderExamPrep();if(view.screen==='strict-exam')return renderStrictExam();if(view.screen==='sprooch')return renderSprooch();if(view.screen==='sprooch-detail')return renderSproochDetail();return renderHome();}


function markPwaUpdate(reg){pwaUpdateRegistration=reg;pwaUpdateAvailable=Boolean(reg?.waiting);if(view.screen==='home')renderHome();}
function applyPwaUpdate(){const reg=pwaUpdateRegistration;if(!reg?.waiting)return;reg.waiting.postMessage({type:'SKIP_WAITING'});}
async function registerPwa(){try{const reg=await navigator.serviceWorker.register('/sw.js');pwaUpdateRegistration=reg;if(reg.waiting)markPwaUpdate(reg);reg.addEventListener('updatefound',()=>{const worker=reg.installing;if(!worker)return;worker.addEventListener('statechange',()=>{if(worker.state==='installed'&&navigator.serviceWorker.controller)markPwaUpdate(reg);});});navigator.serviceWorker.addEventListener('controllerchange',()=>{if(pwaUpdateAvailable)location.reload();});}catch{}}

window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstallPrompt=e;if(view.screen==='home')renderHome();});
window.addEventListener('appinstalled',()=>{deferredInstallPrompt=null;if(view.screen==='home')renderHome();});
setInterval(()=>{if(document.visibilityState!=='visible'||!['lesson','book'].includes(view.screen))return;const key=dayKey();state.activity[key]=Number(state.activity[key]||0)+0.5;persist();if(view.screen==='home')renderHome();},30000);
if('serviceWorker' in navigator)window.addEventListener('load',registerPwa);
persist();
render();
